mapper.select:
o.del_flag='0'
        and o.series_id=#{seriesId}
        and ds.study_id=#{studyId}
        and ds.position_id=#{positionId}
        and ds.workpiece_id=#{workpieceId}
        and w.task_id=#{taskId}
        and o.object_type=#{objectType}
        and s.study_instance_uid=#{studyUid}
        and o.sop_instance_uid=#{sopInstanceUid}
        and exists(select 1 from ndt_inspection_task ct
            join ndt_customer cc on cc.id=ct.customer_id and cc.del_flag='0'
            where ct.id=w.task_id and ct.customer_id=#{params.scopeCustomerId} and ct.del_flag='0')
        and exists(select 1 from ndt_task_user tu where tu.task_id=w.task_id and tu.user_id=#{params.scopeUserId} and tu.can_view='1')
        and 1=0
    order by o.create_time desc,o.id desc
